"""Timesheet rows: one line per worker, busiest first."""

from typing import Dict, List
from hourglass.schedule import worker_minutes
from hourglass.models import Shift
from hourglass.errors import ProjectError
from collections import Counter

def check_shifts(shifts: List[Shift]) -> None:
    """Raise ProjectError for no shifts or a blank name."""
    if not shifts:
        raise ProjectError("no shifts given")
    if any(not shift.worker.strip() for shift in shifts):
        raise ProjectError("a shift has no worker name")

def format_hours(minutes: int) -> str:
    """Hours to one decimal place, halves rounded up."""
    tenths = (minutes + 3) // 6
    return f"{tenths // 10}.{tenths % 10}"

def timesheet_line(
    name: str, count: int, minutes: int
) -> str:
    noun = "shift" if count == 1 else "shifts"
    hours = format_hours(minutes)
    return f"{name}: {count} {noun}, {hours} hours"

def busiest_first(totals: Dict[str, int]) -> List[str]:
    """Names by minutes worked, ties sorted by name."""
    return sorted(
        totals, key=lambda name: (-totals[name], name)
    )

def timesheet_rows(shifts: List[Shift]) -> List[str]:
    check_shifts(shifts)
    counts = Counter(shift.worker for shift in shifts)
    totals = worker_minutes(shifts)
    return [
        timesheet_line(name, counts[name], totals[name])
        for name in busiest_first(totals)
    ]
